A map keeps only the children that are actually used. That saves space when a node has very few branches, and it also makes the node work with characters beyond just `a` to `z`.

The helper walks through a string and returns the final node. `search` checks its word flag, while `startsWith` only needs the path to exist.

```cpp
#include <string>
#include <unordered_map>
using namespace std;

class Trie {
private:
    struct Node {
        unordered_map<char, Node*> children;
        bool isWord = false;
    };

    Node* root;

    Node* walk(const string& text) {
        Node* current = root;

        for (char ch : text) {
            auto it = current->children.find(ch);
            if (it == current->children.end()) {
                return nullptr;
            }
            current = it->second;
        }

        return current;
    }

public:
    Trie() {
        root = new Node();
    }

    void insert(string word) {
        Node* current = root;

        for (char ch : word) {
            if (!current->children.count(ch)) {
                current->children[ch] = new Node();
            }
            current = current->children[ch];
        }

        current->isWord = true;
    }

    bool search(string word) {
        Node* node = walk(word);
        return node != nullptr && node->isWord;
    }

    bool startsWith(string prefix) {
        return walk(prefix) != nullptr;
    }
};

/**
