Each operation takes O(L) time, where L is the length of the word or prefix. The trie uses O(S) space, where S is the number of unique characters stored. This assumes lowercase English letters. An empty prefix returns true because the root represents that prefix.

The recursive functions make the movement through the trie easy to follow. Each call handles one character, and the `terminal` flag is set only after the whole word has been consumed.

For a small dry run, insert `dog`: calls create or follow `d`, then `o`, then `g`, and the call at the end marks `g` as terminal. A search for `do` reaches the node but sees `terminal == false`, while `startsWith("do")` succeeds.

```cpp
#include <string>
using namespace std;

class Trie {
private:
    struct Node {
        Node* child[26];
        bool terminal;

        Node() : terminal(false) {
            for (int i = 0; i < 26; ++i) {
                child[i] = nullptr;
            }
        }
    };

    Node* root;

    void add(Node* node, const string& word, int index) {
        if (index == static_cast<int>(word.size())) {
            node->terminal = true;
            return;
        }

        int letter = word[index] - 'a';
        if (node->child[letter] == nullptr) {
            node->child[letter] = new Node();
        }

        add(node->child[letter], word, index + 1);
    }

    Node* find(Node* node, const string& text, int index) {
        if (index == static_cast<int>(text.size())) {
            return node;
        }

        int letter = text[index] - 'a';
        if (node->child[letter] == nullptr) {
            return nullptr;
        }

        return find(node->child[letter], text, index + 1);
    }

public:
    Trie() {
        root = new Node();
    }

    void insert(string word) {
        add(root, word, 0);
    }

    bool search(string word) {
        Node* node = find(root, word, 0);
        return node != nullptr && node->terminal;
    }

    bool startsWith(string prefix) {
        return find(root, prefix, 0) != nullptr;
    }
};

